1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioOutput {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	/**
68	 * What each item is insured FOR — distinct from its base premium above.
69	 * A block of 3 alike components discounts the premium only, never this sum.
70	 */
71	const INSURANCE_VALUES: Record<string, number> = {
72	  sword: 1000,
73	  amulet: 600,
74	  staff: 800,
75	  potion: 400,
76	  rune: 250,
77	  moonstone: 250,
78	};
79	
80	const DEDUCTIBLE_PER_DAMAGE = 100;
81	const CAP_MULTIPLIER = 2;
82	
83	/**
84	 * The spec states ONE rounding rule — "in the MHPCO's favour" — but it resolves
85	 * to OPPOSITE directions on the two sides of the ledger: money coming in rounds
86	 * up, money going out rounds down. Because that asymmetry is counterintuitive
87	 * for a single rule, the direction is in each NAME and not only in a comment:
88	 * a call site then reads as its own check, and a swapped `ceil`/`floor`
89	 * contradicts the name rather than merely contradicting prose.
90	 *
91	 * They are deliberately NOT unified behind one helper with a direction
92	 * parameter: the shape is shared but the knowledge is not, and a parameter
93	 * would restore exactly the opacity that naming these two things removes.
94	 */
95	const roundPremiumUp = (amount: number): number => Math.ceil(amount);
96	
97	const roundPayoutDown = (amount: number): number => Math.floor(amount);
98	
99	const policyCap = (items: Item[]): number =>
100	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0) *
101	  CAP_MULTIPLIER;
102	
103	/** Damage to a very highly enchanted item is only half reimbursed. */
104	const REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
105	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
106	
107	/** The share of a damage amount the MHPCO reimburses, before the deductible. */
108	const reimbursementRate = (item: Item): number =>
109	  (item.enchantment ?? 0) >= REIMBURSEMENT_ENCHANTMENT_THRESHOLD
110	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
111	    : 1;
112	
113	/**
114	 * Resolves each damage to the insured item it refers to, rejecting any the
115	 * policy does not cover and any negative amount. Run BEFORE any payout
116	 * arithmetic so a rejected claim leaves the policy's remaining cap untouched —
117	 * a negative amount would otherwise REFUND cap, raising it above its start.
118	 *
119	 * Only negatives are rejected: the spec says nothing about an amount of 0.
120	 */
121	const damagedItems = (incident: Incident, insuredItems: Item[]): Item[] => {
122	  // Per-type COUNTS, not per-type identity: two sword damages are legitimate
123	  // against two insured swords but must be rejected against one. A
124	  // Map<type, Item> lookup would collapse exactly this distinction.
125	  const insuredCounts = countByType(insuredItems);
126	  const claimedCounts = new Map<string, number>();
127	
128	  return incident.damages.map((damage) => {
129	    if (damage.amount < 0) {
130	      throw new Error(`Damage amount cannot be negative: ${damage.amount}`);
131	    }
132	
133	    const claimed = (claimedCounts.get(damage.itemType) ?? 0) + 1;
134	    claimedCounts.set(damage.itemType, claimed);
135	    if (claimed > (insuredCounts.get(damage.itemType) ?? 0)) {
136	      throw new Error(
137	        `More damage entries than insured items of type: ${damage.itemType}`,
138	      );
139	    }
140	
141	    const item = insuredItems.find(
142	      (candidate) => candidate.type === damage.itemType,
143	    );
144	    if (item === undefined) {
145	      throw new Error(`Damaged item not covered by policy: ${damage.itemType}`);
146	    }
147	    return item;
148	  });
149	};
150	
151	const claimPayout = (
152	  incident: Incident,
153	  insuredItems: Item[],
154	  remainingCap: number,
155	): number => {
156	  const items = damagedItems(incident, insuredItems);
157	
158	  // Reimburse first, deduct second: a 1000 G damage at 50 % is 500 − 100 = 400,
159	  // not (1000 − 100) / 2 = 450.
160	  const reimbursed = incident.damages.reduce(
161	    (sum, damage, index) =>
162	      sum +
163	      damage.amount * reimbursementRate(items[index]) -
164	      DEDUCTIBLE_PER_DAMAGE,
165	    0,
166	  );
167	  // Rounded HERE, AFTER the cap clamp — the order is load-bearing, not
168	  // incidental. One integer then flows into both the reported payout and the cap
169	  // decrement; rounding before the clamp instead leaves a fraction in the
170	  // remaining cap even when the reported payout itself reads clean.
171	  return roundPayoutDown(Math.min(reimbursed, remainingCap));
172	};
173	
174	const BLOCK_SIZE = 3;
175	const BLOCK_BASE_PREMIUM = 60;
176	
177	const countByType = (items: Item[]): Map<string, number> => {
178	  const counts = new Map<string, number>();
179	  for (const item of items) {
180	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
181	  }
182	  return counts;
183	};
184	
185	/** A group of exactly 3 alike components is priced as one building block. */
186	const groupBasePremium = (type: string, count: number): number =>
187	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
188	
189	const LOYALTY_DISCOUNT_RATE = 0.2;
190	const LOYALTY_YEARS_THRESHOLD = 2;
191	const FOLLOWUP_DISCOUNT_RATE = 0.15;
192	
193	const CURSE_SURCHARGE_RATE = 0.5;
194	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
195	const SURCHARGE_ENCHANTMENT_THRESHOLD = 5;
196	
197	/**
198	 * Rates are SUMMED here and multiplied by the base premium once by the caller,
199	 * so two modifiers on one item are additive (0.5 + 0.3) rather than
200	 * compounding (× 1.5 × 1.3) — per the spec's integration example.
201	 */
202	const itemSurchargeRate = (item: Item): number => {
203	  const curseRate = item.cursed ? CURSE_SURCHARGE_RATE : 0;
204	  const highEnchantmentRate =
205	    (item.enchantment ?? 0) >= SURCHARGE_ENCHANTMENT_THRESHOLD
206	      ? HIGH_ENCHANTMENT_SURCHARGE_RATE
207	      : 0;
208	  return curseRate + highEnchantmentRate;
209	};
210	
211	/**
212	 * Item-specific surcharges apply to the affected item's OWN base premium, so
213	 * they need a per-item pass — the grouping in `countByType` collapses both
214	 * `cursed` and `enchantment`.
215	 */
216	const itemSurcharges = (items: Item[]): number =>
217	  items.reduce(
218	    (sum, item) => sum + BASE_PREMIUMS[item.type] * itemSurchargeRate(item),
219	    0,
220	  );
221	
222	/**
223	 * Rejects items the MHPCO does not underwrite. Keyed off BASE_PREMIUMS, whose
224	 * key set is identical to INSURANCE_VALUES', so one check covers both lookups.
225	 * Throws rather than reporting: the CLI turns this into stderr + a non-zero
226	 * exit, keeping process concerns out of this module.
227	 */
228	const assertKnownItemTypes = (items: Item[]): void => {
229	  for (const item of items) {
230	    if (!(item.type in BASE_PREMIUMS)) {
231	      throw new Error(`Unknown item type: ${item.type}`);
232	    }
233	  }
234	};
235	
236	/** Is this contract a follow-up, i.e. not the customer's first in the run? */
237	const isFollowUpContract = (stepIndex: number): boolean => stepIndex > 0;
238	
239	const quotePremium = (
240	  step: QuoteStep,
241	  customer: Customer,
242	  stepIndex: number,
243	): number => {
244	  assertKnownItemTypes(step.items);
245	
246	  // Policy-scoped modifiers below are percentages of THIS total, never of a
247	  // running total — hence the explicit `policy` in the name: item surcharges
248	  // are percentages of each item's OWN base premium instead.
249	  const policyBasePremium = [...countByType(step.items)].reduce(
250	    (sum, [type, count]) => sum + groupBasePremium(type, count),
251	    0,
252	  );
253	
254	  /**
255	   * A conditional policy-scoped modifier: a rate on the policy base premium,
256	   * applied only when it is due. The two users differ solely in rate and
257	   * predicate — and deliberately in their INPUT: loyalty reads the customer,
258	   * the follow-up discount reads the step's position. That difference in input
259	   * is why the terms stay separate in the sum below rather than collapsing
260	   * into one lumped "adjustments" subtotal.
261	   */
262	  const policyModifier = (rate: number, isDue: boolean): number =>
263	    isDue ? policyBasePremium * rate : 0;
264	
265	  // Unconditional — every item in a quote counts as a first insurance — so it
266	  // does not go through `policyModifier`, which exists to gate a rate.
267	  const firstInsuranceSurcharge =
268	    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
269	  const loyaltyDiscount = policyModifier(
270	    LOYALTY_DISCOUNT_RATE,
271	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
272	  );
273	  const followUpDiscount = policyModifier(
274	    FOLLOWUP_DISCOUNT_RATE,
275	    isFollowUpContract(stepIndex),
276	  );
277	
278	  return (
279	    policyBasePremium +
280	    itemSurcharges(step.items) +
281	    firstInsuranceSurcharge -
282	    loyaltyDiscount -
283	    followUpDiscount +
284	    PROCESSING_FEE
285	  );
286	};
287	
288	/** A policy as it stands: what it covers, and how much cap it has left. */
289	interface PolicyState {
290	  items: Item[];
291	  remainingCap: number;
292	}
293	
294	/**
295	 * Settles one claim against its policy's remaining cap, DECREMENTING that cap
296	 * in `policiesByStepIndex` — successive claims on one policy must each see the
297	 * previous one's decrement, so this is deliberately not a pure function.
298	 */
299	const claimResult = (
300	  step: ClaimStep,
301	  policiesByStepIndex: Map<number, PolicyState>,
302	): ClaimResult => {
303	  // PLACEHOLDER, not intended behaviour: a claim naming a policy that no quote
304	  // step created currently reads as an empty policy with zero cap, so it pays
305	  // out 0. Such a claim must be REJECTED; the pending dangling-policy test owns
306	  // replacing this.
307	  const policy = policiesByStepIndex.get(step.policy) ?? {
308	    items: [],
309	    remainingCap: 0,
310	  };
311	  const payout = claimPayout(step.incident, policy.items, policy.remainingCap);
312	  const remainingCap = policy.remainingCap - payout;
313	  policiesByStepIndex.set(step.policy, { ...policy, remainingCap });
314	  return { payout, remainingCap };
315	};
316	
317	export const runScenario = (scenario: Scenario): ScenarioOutput => {
318	  // Claim steps reference a policy by the index of the quote step that created
319	  // it, and the remaining cap persists across claims — so the steps cannot be
320	  // processed independently of one another. That cross-step state is why this
321	  // stays an explicit loop: a fold would have to carry both the result list and
322	  // this ledger in one accumulator, hiding the sequencing rather than showing it.
323	  const policiesByStepIndex = new Map<number, PolicyState>();
324	  const results: StepResult[] = [];
325	
326	  scenario.steps.forEach((step, stepIndex) => {
327	    if (step.op === "quote") {
328	      policiesByStepIndex.set(stepIndex, {
329	        items: step.items,
330	        remainingCap: policyCap(step.items),
331	      });
332	      results.push({
333	        premium: roundPremiumUp(
334	          quotePremium(step, scenario.customer, stepIndex),
335	        ),
336	      });
337	    } else {
338	      results.push(claimResult(step, policiesByStepIndex));
339	    }
340	  });
341	
342	  return { results };
343	};
344

1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Simplest case ---
6	  it("should charge only the processing fee for an empty item list — premium 5 G", () => {
7	    const output = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(output).toEqual({ results: [{ premium: 5 }] });
13	  });
14	
15	  // --- Item base premiums (each + 5 G fee + 10 G first insurance) ---
16	  // Base premium 100 G; end-to-end for a 0-year customer this is
17	  // 100 base + 10 first-insurance surcharge + 5 processing fee = 115 G.
18	  it("should quote a plain sword — base premium 100 G", () => {
19	    const output = runScenario({
20	      customer: { yearsWithMHPCO: 0 },
21	      steps: [
22	        { op: "quote", items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }] },
23	      ],
24	    });
25	
26	    expect(output).toEqual({ results: [{ premium: 115 }] });
27	  });
28	  // Base premium 60 G; end-to-end for a 0-year customer this is
29	  // 60 base + 6 first-insurance surcharge + 5 processing fee = 71 G.
30	  it("should quote a plain amulet — base premium 60 G", () => {
31	    const output = runScenario({
32	      customer: { yearsWithMHPCO: 0 },
33	      steps: [
34	        { op: "quote", items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }] },
35	      ],
36	    });
37	
38	    expect(output).toEqual({ results: [{ premium: 71 }] });
39	  });
40	  // Base premium 80 G; end-to-end for a 0-year customer this is
41	  // 80 base + 8 first-insurance surcharge + 5 processing fee = 93 G.
42	  it("should quote a plain staff — base premium 80 G", () => {
43	    const output = runScenario({
44	      customer: { yearsWithMHPCO: 0 },
45	      steps: [
46	        { op: "quote", items: [{ type: "staff", material: "oak", enchantment: 1, cursed: false }] },
47	      ],
48	    });
49	
50	    expect(output).toEqual({ results: [{ premium: 93 }] });
51	  });
52	  // Base premium 40 G; end-to-end for a 0-year customer this is
53	  // 40 base + 4 first-insurance surcharge + 5 processing fee = 49 G.
54	  it("should quote a plain potion — base premium 40 G", () => {
55	    const output = runScenario({
56	      customer: { yearsWithMHPCO: 0 },
57	      steps: [
58	        { op: "quote", items: [{ type: "potion", material: "glass", enchantment: 0, cursed: false }] },
59	      ],
60	    });
61	
62	    expect(output).toEqual({ results: [{ premium: 49 }] });
63	  });
64	  // Components are insured at 250 G with a 25 G base premium each.
65	  // End-to-end for a 0-year customer: 25 base + 2.5 first-insurance
66	  // surcharge + 5 fee = 32.5, rounded UP in the MHPCO's favour = 33 G.
67	  it("should quote a single rune component — base premium 25 G", () => {
68	    const output = runScenario({
69	      customer: { yearsWithMHPCO: 0 },
70	      steps: [{ op: "quote", items: [{ type: "rune" }] }],
71	    });
72	
73	    expect(output).toEqual({ results: [{ premium: 33 }] });
74	  });
75	  // Moonstone is the second component type, also 25 G base premium.
76	  // End-to-end: 25 + 2.5 + 5 = 32.5, rounded UP = 33 G (as for a rune).
77	  it("should quote a single moonstone component — base premium 25 G", () => {
78	    const output = runScenario({
79	      customer: { yearsWithMHPCO: 0 },
80	      steps: [{ op: "quote", items: [{ type: "moonstone" }] }],
81	    });
82	
83	    expect(output).toEqual({ results: [{ premium: 33 }] });
84	  });
85	
86	  // --- Building block of 3 alike components ---
87	  // 2 × 25 = 50 G base; a block needs EXACTLY 3 alike components, so no
88	  // discount applies. End-to-end: 50 + 5 + 5 = 60 G.
89	  it("should quote 2 runes — base premium 50 G (no block)", () => {
90	    const output = runScenario({
91	      customer: { yearsWithMHPCO: 0 },
92	      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
93	    });
94	
95	    expect(output).toEqual({ results: [{ premium: 60 }] });
96	  });
97	  // A building block of EXACTLY 3 alike components costs 60 G base
98	  // instead of 3 × 25 = 75 G. End-to-end: 60 + 6 + 5 = 71 G.
99	  it("should quote 3 runes — base premium 60 G (block applies)", () => {
100	    const output = runScenario({
101	      customer: { yearsWithMHPCO: 0 },
102	      steps: [
103	        { op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] },
104	      ],
105	    });
106	
107	    expect(output).toEqual({ results: [{ premium: 71 }] });
108	  });
109	  // 4 × 25 = 100 G base — NOT block+1 (which would be 60 + 25 = 85).
110	  // A block requires exactly 3. End-to-end: 100 + 10 + 5 = 115 G.
111	  it("should quote 4 runes — base premium 100 G (no block — block requires exactly 3)", () => {
112	    const output = runScenario({
113	      customer: { yearsWithMHPCO: 0 },
114	      steps: [
115	        {
116	          op: "quote",
117	          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }],
118	        },
119	      ],
120	    });
121	
122	    expect(output).toEqual({ results: [{ premium: 115 }] });
